import { createFileRoute } from "@tanstack/react-router";
import { buttonVariants } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { seo } from "@/lib/seo";

export const Route = createFileRoute("/pricing")({
  head: () => seo({ path: "/pricing", title: "Pricing" }),
  component: Pricing,
});

const plans = [
  { name: "Loaf a week", price: "£6", text: "One sourdough loaf every Saturday." },
  { name: "Two a week", price: "£11", text: "A loaf on Wednesday and on Saturday." },
  { name: "Family", price: "£20", text: "Two loaves and a rye every Saturday." },
];

function Pricing() {
  return (
    <main className="mx-auto max-w-5xl px-6 py-16">
      <h1 className="text-3xl font-semibold">Bread subscriptions</h1>
      <div className="mt-8 grid gap-4 sm:grid-cols-3">
        {plans.map((plan) => (
          <Card key={plan.name}>
            <CardContent className="flex flex-col gap-2">
              <h2 className="font-medium">{plan.name}</h2>
              <p className="text-2xl">{plan.price}</p>
              <p className="text-sm text-muted-foreground">{plan.text}</p>
              <a href="/subscribe" className={buttonVariants()}>
                Subscribe
              </a>
            </CardContent>
          </Card>
        ))}
      </div>
    </main>
  );
}
